'use client';

import { createContext, useContext, useMemo } from 'react';
import type { Locale } from './config';
import type { ClientDictionary } from './dictionaries';

const LocaleContext = createContext<{ locale: Locale; t: ClientDictionary } | null>(null);

// A namespace this part of the tree was not shipped. The scope manifest
// (src/i18n/scopes.generated.ts) is computed by an over-inclusive scan and
// regenerated by every build, so this should never happen; if it does, the
// strings render empty and the console names the namespace, instead of a
// TypeError taking the whole page down.
const EMPTY = Object.freeze({}) as never;
const warned = new Set<string>();
function guarded(dict: Partial<ClientDictionary>): ClientDictionary {
  return new Proxy(dict as ClientDictionary, {
    get(target, key, receiver) {
      if (typeof key !== 'string' || key in target) return Reflect.get(target, key, receiver);
      // React and devtools probe objects (`$$typeof`, `then`, `toJSON`…); only a
      // plain camelCase name can be a namespace.
      if (!/^[a-z][A-Za-z0-9]*$/.test(key) || key === 'then' || key === 'toJSON') return undefined;
      if (!warned.has(key)) {
        warned.add(key);
        console.error(`[i18n] namespace "${key}" was not shipped to this page — run \`npm run i18n:scopes\` (scripts/i18n-scopes.mjs)`);
      }
      return EMPTY;
    },
  });
}

export function LocaleProvider({
  locale,
  dict,
  children,
}: {
  locale: Locale;
  /** The shell namespaces (src/app/layout.tsx); a segment adds its own with DictionaryScope. */
  dict: Partial<ClientDictionary>;
  children: React.ReactNode;
}) {
  const value = useMemo(() => ({ locale, t: guarded(dict) }), [locale, dict]);
  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

/**
 * Adds a segment's namespaces to the ones above it. Rendered by <I18nScope>
 * (src/i18n/scope.tsx) in each top-level layout, because the root layout — and
 * so its LocaleProvider — survives client navigations: what a page needs beyond
 * the shell has to arrive with the page's own segment.
 */
export function DictionaryScope({ dict, children }: { dict: Partial<ClientDictionary>; children: React.ReactNode }) {
  const parent = useLocaleContext();
  const value = useMemo(() => ({ locale: parent.locale, t: guarded({ ...parent.t, ...dict }) }), [parent, dict]);
  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

function useLocaleContext() {
  const ctx = useContext(LocaleContext);
  if (!ctx) throw new Error('useT/useLocale must be used within LocaleProvider');
  return ctx;
}

// Client-side translation hook — returns the active dictionary (client subset;
// server-only namespaces like `landing` are not shipped to the browser, and of
// the rest only what this part of the app uses: see scripts/i18n-scopes.mjs).
export function useT(): ClientDictionary {
  return useLocaleContext().t;
}

export function useLocale(): Locale {
  return useLocaleContext().locale;
}
